import 'dart:convert';
import 'package:csv/csv.dart';
import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import 'package:path/path.dart' as p;
import 'package:share_plus/share_plus.dart';
import 'package:sqflite/sqflite.dart';

const green = Color(0xFF267A60);
const navy = Color(0xFF142238);
final fmt = NumberFormat.currency(locale: 'en_IN', symbol: '₹', decimalDigits: 2);
const cats = ['Food & groceries','Transport','Shopping','Bills & utilities','Rent & home','Health','Salary','Business','Refund','Other'];

Future<void> main() async { WidgetsFlutterBinding.ensureInitialized(); await Store.instance.init(); runApp(const MoneyMind()); }
class MoneyMind extends StatelessWidget { const MoneyMind({super.key}); @override Widget build(BuildContext context)=>MaterialApp(title:'MoneyMind',debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:green),useMaterial3:true,scaffoldBackgroundColor:const Color(0xFFF5F7FA)),home:const Home()); }
class Entry {
 final int? id; final double amount; final String kind,category,merchant,date,source,fingerprint;
 Entry({this.id,required this.amount,required this.kind,required this.category,required this.merchant,required this.date,required this.source,required this.fingerprint});
 Map<String,Object?> map()=>{'id':id,'amount':amount,'kind':kind,'category':category,'merchant':merchant,'date':date,'source':source,'fingerprint':fingerprint};
 factory Entry.from(Map<String,Object?> m)=>Entry(id:m['id'] as int?,amount:(m['amount'] as num).toDouble(),kind:m['kind'] as String,category:m['category'] as String,merchant:m['merchant'] as String,date:m['date'] as String,source:m['source'] as String,fingerprint:m['fingerprint'] as String);
}
class Store {
 Store._(); static final instance=Store._(); Database? db;
 Future<void> init() async { final d=await getDatabasesPath(); db=await openDatabase(p.join(d,'moneymind.db'),version:1,onCreate:(d,v) async {await d.execute('CREATE TABLE entries(id INTEGER PRIMARY KEY AUTOINCREMENT,amount REAL,kind TEXT,category TEXT,merchant TEXT,date TEXT,source TEXT,fingerprint TEXT UNIQUE)');await d.execute('CREATE TABLE budgets(category TEXT PRIMARY KEY,amount REAL)');}); }
 Future<List<Entry>> all() async=>(await db!.query('entries',orderBy:'date DESC')).map(Entry.from).toList();
 Future<void> add(Entry e) async {await db!.insert('entries',e.map()..remove('id'),conflictAlgorithm:ConflictAlgorithm.ignore);}
 Future<void> remove(int id) async {await db!.delete('entries',where:'id=?',whereArgs:[id]);}
 Future<Map<String,double>> getBudgets() async {final rows=await db!.query('budgets');return {for(final r in rows) r['category'] as String:(r['amount'] as num).toDouble()};}
 Future<void> setBudget(String c,double a) async {await db!.insert('budgets',{'category':c,'amount':a},conflictAlgorithm:ConflictAlgorithm.replace);}
}
class Home extends StatefulWidget {const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{
 List<Entry> entries=[];Map<String,double> budgets={};bool busy=true;
 @override void initState(){super.initState();refresh();}
 Future<void> refresh() async {final e=await Store.instance.all();final b=await Store.instance.getBudgets();if(mounted)setState((){entries=e;budgets=b;busy=false;});}
 double total(String k)=>entries.where((e)=>e.kind==k).fold(0,(a,e)=>a+e.amount);
 String categoryFor(String text,bool income){if(income)return text.toLowerCase().contains('salary')?'Salary':'Other';final s=text.toLowerCase();if(RegExp(r'grocery|supermarket|milk|vegetable|blinkit|zepto').hasMatch(s))return cats[0];if(RegExp(r'uber|ola|metro|petrol|fuel|rapido').hasMatch(s))return cats[1];if(RegExp(r'amazon|flipkart|myntra|shopping').hasMatch(s))return cats[2];if(RegExp(r'electricity|water|gas|recharge|bill').hasMatch(s))return cats[3];if(RegExp(r'hospital|pharmacy|medical|clinic').hasMatch(s))return cats[5];return 'Other';}
 Future<void> addManual() async {final amount=TextEditingController(),merchant=TextEditingController();String kind='Expense',category='Other';final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('Add transaction'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Amount (₹)')),TextField(controller:merchant,decoration:const InputDecoration(labelText:'Description')),DropdownButtonFormField<String>(initialValue:kind,items:['Expense','Income'].map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>setD(()=>kind=v!)),DropdownButtonFormField<String>(initialValue:category,items:cats.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>setD(()=>category=v!))])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));final n=double.tryParse(amount.text);if(ok!=true||n==null||n<=0)return;await Store.instance.add(Entry(amount:n,kind:kind,category:category,merchant:merchant.text.trim().isEmpty?category:merchant.text.trim(),date:DateTime.now().toIso8601String(),source:'manual',fingerprint:'manual-${DateTime.now().microsecondsSinceEpoch}'));await refresh();}
 Future<void> setBudget() async {final amount=TextEditingController();String category=cats[0];final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('Monthly category budget'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:category,items:cats.map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(v)=>setD(()=>category=v!)),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Limit in ₹'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));final n=double.tryParse(amount.text);if(ok==true&&n!=null&&n>0){await Store.instance.setBudget(category,n);await refresh();}}
 Future<void> exportCsv() async {final rows=<List<dynamic>>[['Date','Type','Amount INR','Category','Description','Source'],...entries.map((e)=>[e.date,e.kind,e.amount,e.category,e.merchant,e.source])];final csv=const ListToCsvConverter().convert(rows);await Share.shareXFiles([XFile.fromData(utf8.encode(csv),mimeType:'text/csv',name:'moneymind.csv')],text:'MoneyMind export');}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('MoneyMind',style:TextStyle(fontWeight:FontWeight.bold)),actions:[IconButton(onPressed:exportCsv,tooltip:'Export CSV',icon:const Icon(Icons.ios_share)),PopupMenuButton<String>(onSelected:(v){if(v=='budget')setBudget();if(v=='privacy')showDialog<void>(context:context,builder:(c)=>AlertDialog(title:const Text('Privacy'),content:const Text('MoneyMind does not read payment notifications or SMS. Transactions are added only when you enter them manually. Your records are stored locally on this device.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));},itemBuilder:(_)=>const [PopupMenuItem(value:'budget',child:Text('Manage budgets')),PopupMenuItem(value:'privacy',child:Text('Privacy'))])]),floatingActionButton:FloatingActionButton.extended(onPressed:addManual,icon:const Icon(Icons.add),label:const Text('Add transaction')),body:busy?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:refresh,child:ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:navy,borderRadius:BorderRadius.circular(24)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('NET CASH FLOW',style:TextStyle(color:Colors.white70)),const SizedBox(height:8),Text(fmt.format(total('Income')-total('Expense')),style:const TextStyle(color:Colors.white,fontSize:30,fontWeight:FontWeight.bold)),const SizedBox(height:18),Row(children:[Expanded(child:metric('Income',total('Income'),Colors.greenAccent)),const SizedBox(width:10),Expanded(child:metric('Expenses',total('Expense'),const Color(0xFFFFB8B8)))])])),const SizedBox(height:20),Row(children:[const Expanded(child:Text('Monthly budgets',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18))),TextButton(onPressed:setBudget,child:const Text('Manage'))]),if(budgets.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(14),child:Text('Set category budgets to track your spending.')))else ...budgets.entries.map((b){final spent=entries.where((e)=>e.kind=='Expense'&&e.category==b.key&&DateTime.tryParse(e.date)?.month==DateTime.now().month).fold(0.0,(a,e)=>a+e.amount);return Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(b.key)),Text('${fmt.format(spent)} / ${fmt.format(b.value)}')]),const SizedBox(height:8),LinearProgressIndicator(value:(spent/b.value).clamp(0.0,1.0),color:spent>=b.value?Colors.red:green)])));}),const SizedBox(height:12),Row(children:[const Expanded(child:Text('Transactions',style:TextStyle(fontWeight:FontWeight.bold,fontSize:18))),Text('${entries.length} records')]),if(entries.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(24),child:Text('No transactions yet. Tap Add transaction to enter your first record.',textAlign:TextAlign.center)))else ...entries.take(100).map((e)=>Card(child:ListTile(leading:CircleAvatar(child:Icon(e.kind=='Income'?Icons.south_west:Icons.north_east)),title:Text(e.merchant,maxLines:1,overflow:TextOverflow.ellipsis),subtitle:Text('${e.category} • ${DateFormat('d MMM, h:mm a').format(DateTime.tryParse(e.date)?.toLocal()??DateTime.now())}'),trailing:Text('${e.kind=='Income'?'+':'−'}${fmt.format(e.amount)}',style:TextStyle(fontWeight:FontWeight.bold,color:e.kind=='Income'?green:navy)),onLongPress:()=>deleteEntry(e)))),const SizedBox(height:80)])));
 Widget metric(String label,double amount,Color c)=>Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.white.withValues(alpha: .08),borderRadius:BorderRadius.circular(14)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:const TextStyle(color:Colors.white70)),const SizedBox(height:6),Text(fmt.format(amount),style:TextStyle(color:c,fontWeight:FontWeight.bold,fontSize:17))]));
 Future<void> deleteEntry(Entry e) async {if(e.id==null)return;final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Delete transaction?'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Delete'))]));if(ok==true){await Store.instance.remove(e.id!);await refresh();}}
}
